//! Parity of the Rust capital / xVA kernels with Python (`qp_core.capital`,
//! `qp_core.xva`) on the shared fixture generated by
//! `python -m qp_core.xva._parity`.

use qp_core::xva::{
    Hazard, HullWhite, default_leg, eepe, fva, pfe_index, saccr_ir_effective_notional,
    saccr_maturity_factor, saccr_multiplier, saccr_single_factor_addon, saccr_supervisory_delta,
    saccr_supervisory_duration,
};

fn close(got: f64, want: f64, what: &str) {
    let tol = 1e-13 * want.abs().max(1e-2);
    assert!(
        (got - want).abs() <= tol,
        "{what}: got {got:e}, want {want:e}"
    );
}

struct Rec<'a>(std::str::SplitWhitespace<'a>);
impl Rec<'_> {
    fn f(&mut self) -> f64 {
        self.0.next().unwrap().parse().unwrap()
    }
    fn u(&mut self) -> usize {
        self.0.next().unwrap().parse().unwrap()
    }
    fn b(&mut self) -> bool {
        self.u() == 1
    }
    fn v(&mut self, n: usize) -> Vec<f64> {
        (0..n).map(|_| self.f()).collect()
    }
}

#[test]
fn matches_python_fixture() {
    let text = include_str!("data/xva_capital_parity.txt");
    let mut seen = 0;
    for line in text
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
    {
        let mut it = line.split_whitespace();
        let kind = it.next().unwrap();
        let mut r = Rec(it);
        match kind {
            "SD" => {
                let (s, e, w) = (r.f(), r.f(), r.f());
                close(saccr_supervisory_duration(s, e).unwrap(), w, line);
            }
            "DELTA" => {
                let (p, k, v, t, c, b, sh, w) =
                    (r.f(), r.f(), r.f(), r.f(), r.b(), r.b(), r.f(), r.f());
                close(
                    saccr_supervisory_delta(p, k, v, t, c, b, sh).unwrap(),
                    w,
                    line,
                );
            }
            "MF" => {
                let (m, mp, w) = (r.f(), r.f(), r.f());
                close(
                    saccr_maturity_factor(m, (mp >= 0.0).then_some(mp)).unwrap(),
                    w,
                    line,
                );
            }
            "MULT" => {
                let (v, c, a, w) = (r.f(), r.f(), r.f(), r.f());
                close(saccr_multiplier(v, c, a).unwrap(), w, line);
            }
            "IREN" => {
                let (a, b, c, w) = (r.f(), r.f(), r.f(), r.f());
                close(saccr_ir_effective_notional(a, b, c), w, line);
            }
            "SFA" => {
                let n = r.u();
                let (a, rho, w) = (r.v(n), r.v(n), r.f());
                close(saccr_single_factor_addon(&a, &rho).unwrap(), w, line);
            }
            "ZBO" => {
                let hw = HullWhite::new(r.f(), r.f()).unwrap();
                let (t, s, pt, ps, x, call, w) = (r.f(), r.f(), r.f(), r.f(), r.f(), r.b(), r.f());
                close(hw.zcb_option(t, s, pt, ps, x, call).unwrap(), w, line);
            }
            "SWPT" => {
                let hw = HullWhite::new(r.f(), r.f()).unwrap();
                let (t0, p0) = (r.f(), r.f());
                let n = r.u();
                let (pay, pp, acc) = (r.v(n), r.v(n), r.v(n));
                let (k, payer, w) = (r.f(), r.b(), r.f());
                close(
                    hw.swaption(t0, p0, &pay, &pp, &acc, k, payer).unwrap(),
                    w,
                    line,
                );
            }
            "XVA" => {
                let m = r.u();
                let (t, ee, ene) = (r.v(m), r.v(m), r.v(m));
                let hct = [r.f(), r.f()];
                let hch = [r.f(), r.f()];
                let hbt = [r.f()];
                let hbh = [r.f()];
                let hc = Hazard {
                    times: &hct,
                    hazards: &hch,
                };
                let hb = Hazard {
                    times: &hbt,
                    hazards: &hbh,
                };
                let (c1, c2, fca, fba) = (r.f(), r.f(), r.f(), r.f());
                close(default_leg(&t, &ee, hc, 0.4, None).unwrap(), c1, "cva");
                close(
                    default_leg(&t, &ee, hc, 0.4, Some(hb)).unwrap(),
                    c2,
                    "cva bilateral",
                );
                let (f, b) = fva(&t, &ee, &ene, 0.01, 0.004, hc, hb).unwrap();
                close(f, fca, "fca");
                close(b, fba, "fba");
            }
            "EEPE" => {
                let m = r.u();
                let (t, ee, mat, w) = (r.v(m), r.v(m), r.f(), r.f());
                close(eepe(&t, &ee, mat).unwrap(), w, line);
            }
            "PFE" => {
                let (n, q, w) = (r.u(), r.f(), r.u());
                assert_eq!(pfe_index(n, q).unwrap(), w, "{line}");
            }
            other => panic!("unknown record {other}"),
        }
        seen += 1;
    }
    assert_eq!(seen, 53);
}

#[test]
fn bcbs_example_1_end_to_end() {
    // BCBS 279 Annex 4a Example 1: EAD 569 thousand.
    let sd = |s, e| saccr_supervisory_duration(s, e).unwrap();
    let delta = saccr_supervisory_delta(0.06, 0.05, 0.5, 1.0, false, true, 0.0).unwrap();
    let usd = saccr_ir_effective_notional(0.0, -10_000.0 * sd(0.0, 4.0), 10_000.0 * sd(0.0, 10.0));
    let eur = saccr_ir_effective_notional(0.0, 0.0, delta * 5_000.0 * sd(1.0, 11.0));
    let addon = 0.005 * (usd + eur);
    let ead = 1.4 * (60.0 + saccr_multiplier(60.0, 0.0, addon).unwrap() * addon);
    assert_eq!((addon.round(), ead.round()), (347.0, 569.0));
}

#[test]
fn rejects_bad_input() {
    assert!(saccr_supervisory_duration(5.0, 1.0).is_err());
    assert!(HullWhite::new(0.0, 0.01).is_err());
    assert!(pfe_index(0, 0.5).is_err());
}
